/* ════════════════════════════════════════════════════════════
   UNIT — JS
   Three.js spatial scenes (ambient field, hero AI core, neural
   skill orbit), CSS-3D drag carousel, GSAP/ScrollTrigger, Typed.js.
════════════════════════════════════════════════════════════ */

const REDUCE_MOTION = matchMedia('(prefers-reduced-motion: reduce)').matches;
const FINE_POINTER  = matchMedia('(hover: hover) and (pointer: fine)').matches;

/* ── THEME — one definitive palette, no toggle. onThemeChange/THEME_RETINT
   stay as harmless no-op plumbing so the WebGL scenes below (which call
   onThemeChange to wire up retinting) don't need to be touched. ── */
const THEME_RETINT = [];
function onThemeChange(fn){ THEME_RETINT.push(fn); }
function isLightMode(){ return false; }
function threePalette(){
  return { a:0x3fc6ff, b:0x9d4dff, c:0x39f3d6, aHex:'#3fc6ff', bHex:'#9d4dff', cHex:'#39f3d6' };
}

/* ── BOOT — percentage climbs to 99 in step with the frame's grow-in reveal,
   snaps to 100 and holds a beat, then the whole overlay fades. ── */
window.addEventListener('load',()=>{
  const b=document.getElementById('boot'), pct=document.getElementById('bootPct');
  if(pct && !REDUCE_MOTION){
    let n=0;
    const iv=setInterval(()=>{
      n+=Math.max(1,Math.round((99-n)*0.18));
      if(n>=99){ n=99; clearInterval(iv); pct.textContent='100%'; }
      else pct.textContent=n+'%';
    },42);
  } else if(pct){ pct.textContent='100%'; }
  setTimeout(()=>b.classList.add('out'),900);
  setTimeout(()=>b.style.display='none',1300);
});

/* ── HUD CLOCK ── */
(()=>{
  const el=document.getElementById('clock');if(!el)return;
  function tick(){ el.textContent=new Date().toLocaleTimeString('en-GB',{hour12:false}); }
  tick(); setInterval(tick,1000);
})();

/* ── NAV DOCK ── */
(()=>{
  const links=document.querySelectorAll('.navdock a');
  if(!links.length) return;
  const map=new Map();
  links.forEach(a=>{ const id=a.getAttribute('href').slice(1); const sec=document.getElementById(id); if(sec) map.set(sec,a); });
  const obs=new IntersectionObserver(entries=>{
    entries.forEach(en=>{
      const a=map.get(en.target); if(!a) return;
      if(en.isIntersecting){ links.forEach(x=>x.classList.remove('active')); a.classList.add('active'); }
    });
  },{rootMargin:'-45% 0px -45% 0px'});
  map.forEach((a,sec)=>obs.observe(sec));
})();

/* ── CURSOR ── */
(()=>{
  if(!FINE_POINTER) return;
  const dot=document.getElementById('curDot'),ring=document.getElementById('curRing');
  if(!dot||!ring) return;
  document.documentElement.classList.add('has-cursor');
  let mx=innerWidth/2,my=innerHeight/2,rx=mx,ry=my;
  document.addEventListener('mousemove',e=>{
    mx=e.clientX;my=e.clientY;
    dot.style.transform=`translate3d(${mx}px,${my}px,0) translate(-50%,-50%)`;
  });
  (function loop(){
    rx+=(mx-rx)*0.18;ry+=(my-ry)*0.18;
    ring.style.transform=`translate3d(${rx}px,${ry}px,0) translate(-50%,-50%)`;
    requestAnimationFrame(loop);
  })();
  document.addEventListener('mouseover',e=>{
    ring.classList.toggle('big', !!e.target.closest('a,button,.arr-fb,.car-panel'));
  });
})();

/* ── AMBIENT SPATIAL FIELD (full page) ── */
(()=>{
  if(typeof THREE==='undefined' || REDUCE_MOTION) return;
  const canvas=document.getElementById('bgGL');if(!canvas) return;
  const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});
  renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.6));
  const scene=new THREE.Scene();
  const camera=new THREE.PerspectiveCamera(55, innerWidth/innerHeight, 0.1, 100);
  camera.position.z=20;

  const COUNT=900;
  const geo=new THREE.BufferGeometry();
  const pos=new Float32Array(COUNT*3);
  for(let i=0;i<COUNT;i++){
    pos[i*3]=(Math.random()-0.5)*80;
    pos[i*3+1]=(Math.random()-0.5)*190;
    pos[i*3+2]=(Math.random()-0.5)*60-10;
  }
  geo.setAttribute('position',new THREE.BufferAttribute(pos,3));
  const pal0=threePalette();
  const mat=new THREE.PointsMaterial({size:0.09,color:pal0.a,transparent:true,opacity:0.4,depthWrite:false});
  const points=new THREE.Points(geo,mat);
  scene.add(points);

  const shapeGeos=[new THREE.IcosahedronGeometry(1.1,0),new THREE.OctahedronGeometry(0.95,0),new THREE.TorusGeometry(0.8,0.025,8,40),new THREE.DodecahedronGeometry(0.9,0)];
  const shapes=[];
  const WORLD_H=190;
  for(let i=0;i<14;i++){
    const m=new THREE.Mesh(shapeGeos[i%shapeGeos.length], new THREE.MeshBasicMaterial({color:[pal0.a,pal0.b,pal0.c][i%3],wireframe:true,transparent:true,opacity:0.18}));
    const side=Math.random()<0.5?-1:1;
    m.position.set(side*(10+Math.random()*10),(Math.random()-0.5)*WORLD_H,(Math.random()-0.5)*14-12);
    m.userData={sx:(Math.random()-0.5)*0.004,sy:(Math.random()-0.5)*0.005,amp:0.5+Math.random()*0.5,sp:0.2+Math.random()*0.3,off:Math.random()*6.28,baseY:m.position.y};
    scene.add(m);shapes.push(m);
  }
  onThemeChange(()=>{
    const p=threePalette();
    mat.color.setHex(p.a);
    shapes.forEach((m,i)=>m.material.color.setHex([p.a,p.b,p.c][i%3]));
  });

  let mx=0,my=0,scrollPx=0;
  window.addEventListener('mousemove',e=>{mx=(e.clientX/innerWidth-0.5);my=(e.clientY/innerHeight-0.5);});
  window.addEventListener('scroll',()=>{ scrollPx=window.scrollY; });
  function resize(){ renderer.setSize(innerWidth,innerHeight); camera.aspect=innerWidth/innerHeight; camera.updateProjectionMatrix(); }
  window.addEventListener('resize',resize); resize();

  let t=0, camY=0;
  function tick(){
    t+=0.016;
    const targetY=-my*1.4-scrollPx*0.009;
    camY+=(targetY-camY)*0.04;
    camera.position.x+=(mx*2-camera.position.x)*0.02;
    camera.position.y=camY;
    camera.lookAt(camera.position.x*0.3,camY,0);
    points.rotation.y+=0.0004;
    shapes.forEach(m=>{
      m.rotation.x+=m.userData.sx; m.rotation.y+=m.userData.sy;
      m.position.y=m.userData.baseY+Math.sin(t*m.userData.sp+m.userData.off)*m.userData.amp;
    });
    renderer.render(scene,camera);
    requestAnimationFrame(tick);
  }
  tick();
})();

/* ── HERO AURA — large wireframe field behind the subject (not over the face) ── */
(()=>{
  if(typeof THREE==='undefined' || REDUCE_MOTION) return;
  const canvas=document.getElementById('heroAura');if(!canvas) return;
  const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});
  renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.6));
  const scene=new THREE.Scene();
  const camera=new THREE.PerspectiveCamera(42,1,0.1,60);
  camera.position.set(0,0,13);

  const p0=threePalette();
  const core=new THREE.Mesh(new THREE.IcosahedronGeometry(2.6,1), new THREE.MeshBasicMaterial({color:p0.a,wireframe:true,transparent:true,opacity:0.68}));
  scene.add(core);
  const coreInner=new THREE.Mesh(new THREE.IcosahedronGeometry(1.85,1), new THREE.MeshBasicMaterial({color:p0.b,transparent:true,opacity:0.16}));
  scene.add(coreInner);

  const rings=[], ringPal=[p0.a,p0.b,p0.c];
  for(let i=0;i<5;i++){
    const torus=new THREE.Mesh(new THREE.TorusGeometry(4.1+i*0.62,0.022,8,110), new THREE.MeshBasicMaterial({color:ringPal[i%3],transparent:true,opacity:0.8}));
    torus.rotation.x=0.2+i*0.2; torus.rotation.y=i*0.24;
    torus.userData={spin:0.0022+i*0.0009};
    scene.add(torus); rings.push(torus);
  }

  const nodes=[], nodeGeo=new THREE.IcosahedronGeometry(0.13,0);
  for(let i=0;i<20;i++){
    const node=new THREE.Mesh(nodeGeo, new THREE.MeshBasicMaterial({color:ringPal[i%3]}));
    node.userData={r:4.0+(i%5)*0.55,speed:0.26+Math.random()*0.28,offset:Math.random()*6.28,tilt:0.16+(i%5)*0.2};
    scene.add(node); nodes.push(node);
  }

  onThemeChange(()=>{
    const p=threePalette(); const pal=[p.a,p.b,p.c];
    core.material.color.setHex(p.a); coreInner.material.color.setHex(p.b);
    rings.forEach((r,i)=>r.material.color.setHex(pal[i%3]));
    nodes.forEach((n,i)=>n.material.color.setHex(pal[i%3]));
  });

  let mx=0, my=0;
  window.addEventListener('mousemove',e=>{ mx=(e.clientX/innerWidth-0.5); my=(e.clientY/innerHeight-0.5); });

  function resize(){
    const r=canvas.getBoundingClientRect();
    const s=Math.max(r.width,r.height)||600;
    renderer.setSize(s,s,false);
    canvas.style.width='100%'; canvas.style.height='100%';
  }
  window.addEventListener('resize',resize); resize();

  let t=0, rafId=null;
  function tick(){
    t+=0.01;
    core.rotation.y+=0.0016; core.rotation.x+=0.001;
    coreInner.rotation.y-=0.0013;
    coreInner.scale.setScalar(1+Math.sin(t*1.2)*0.05);
    rings.forEach(r=>{ r.rotation.z+=r.userData.spin; });
    nodes.forEach(n=>{
      const a=t*n.userData.speed+n.userData.offset, r=n.userData.r, tilt=n.userData.tilt;
      n.position.set(Math.cos(a)*r, Math.sin(a)*r*Math.sin(tilt), Math.sin(a)*r*Math.cos(tilt));
    });
    scene.rotation.y=Math.sin(t*0.1)*0.18+mx*0.35;
    scene.rotation.x=my*0.22;
    renderer.render(scene,camera);
    rafId=requestAnimationFrame(tick);
  }
  const heroEl=document.getElementById('hero');
  if(heroEl){
    new IntersectionObserver(([e])=>{
      if(e.isIntersecting){ if(!rafId) tick(); }
      else if(rafId){ cancelAnimationFrame(rafId); rafId=null; }
    },{threshold:0.01}).observe(heroEl);
  } else { tick(); }
})();

/* ── HERO PHOTO 3D TILT (cursor-driven parallax on the portrait) ── */
(()=>{
  if(!FINE_POINTER || REDUCE_MOTION) return;
  const hero=document.querySelector('.hero-zone'), wrap=document.querySelector('.hero-photo-wrap');
  if(!hero||!wrap) return;
  hero.addEventListener('mousemove',e=>{
    const r=hero.getBoundingClientRect();
    const px=(e.clientX-r.left)/r.width-0.5, py=(e.clientY-r.top)/r.height-0.5;
    wrap.style.setProperty('--tx',(px*3.2)+'deg');
    wrap.style.setProperty('--ty',(-py*2.4)+'deg');
  });
  hero.addEventListener('mouseleave',()=>{ wrap.style.setProperty('--tx','0deg'); wrap.style.setProperty('--ty','0deg'); });
})();

/* ── GLASS CARD 3D TILT (contact rows, commendation cards, and the bigger
   panels at a gentler angle so they tilt without warping) ── */
(()=>{
  if(!FINE_POINTER || REDUCE_MOTION) return;
  function wireTilt(selector,deg){
    document.querySelectorAll(selector).forEach(el=>{
      el.addEventListener('mousemove',e=>{
        const r=el.getBoundingClientRect();
        const px=(e.clientX-r.left)/r.width-0.5, py=(e.clientY-r.top)/r.height-0.5;
        el.style.transform=`perspective(900px) rotateY(${px*deg}deg) rotateX(${-py*deg}deg) translateY(-3px) translateZ(8px)`;
      });
      el.addEventListener('mouseleave',()=>{ el.style.transform=''; });
    });
  }
  wireTilt('.up-row, .radial-item .ri-inner', 7);
  wireTilt('.spec-grid, .stat-list, .log-col', 2.2);
})();

/* ── LIQUID GLASS GLINT — every frosted surface tracks the cursor and
   brightens a soft specular highlight under it (the --gx/--gy vars the
   .glass::after / .car-panel::after etc. rules in style.css read). ── */
(()=>{
  if(!FINE_POINTER) return;
  document.querySelectorAll('.glass, .car-panel, .up-row, .bx-s, .radial-core').forEach(el=>{
    el.addEventListener('pointermove',e=>{
      const r=el.getBoundingClientRect();
      el.style.setProperty('--gx',((e.clientX-r.left)/r.width*100)+'%');
      el.style.setProperty('--gy',((e.clientY-r.top)/r.height*100)+'%');
    });
  });
})();

/* ── NEURAL ARRAY — WebGL orbiting skill cluster. Each category gets its
   own vivid, distinct neon color (cloud=sky-blue, tools=neon-purple,
   core=hot-rose) instead of one uniform tint cycling arbitrarily — the
   whole point being the cluster should read as colorful at a glance. ── */
const CAT_COLOR={ cloud:'#3fc6ff', tools:'#a855ff', core:'#ff4d8d' };
function svgBadge(label,fill,size){
  return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80"><rect width="80" height="80" rx="14" fill="${fill}"/><text x="40" y="52" text-anchor="middle" fill="#0b0613" font-size="${size}" font-weight="800" font-family="Arial">${label}</text></svg>`);
}
const ICON_B64={
  aws:'data:image/png;base64,',
  azure:'data:image/png;base64,',
  gcp:'data:image/png;base64,',
  burpsuite:'data:image/png;base64,',
  zap:'data:image/png;base64,',
  trivy:'data:image/png;base64,',
  snyk:'data:image/png;base64,',
  checkmarx:'data:image/png;base64,',
  jenkins:'data:image/png;base64,',
  falco:'data:image/png;base64,',
  cilium:'data:image/png;base64,',
  kubearmor:'data:image/png;base64,',
  calico:'data:image/png;base64,',
  kubeBench:'data:image/png;base64,',
};
const SKILL_DATA=[
  {n:'AWS',        cat:'cloud', i:ICON_B64.aws},
  {n:'Azure',      cat:'cloud', i:ICON_B64.azure},
  {n:'GCP',        cat:'cloud', i:ICON_B64.gcp},
  {n:'Kubernetes', cat:'cloud', i:'https://cdn.simpleicons.org/kubernetes/326CE5'},
  {n:'Docker',     cat:'cloud', i:'https://cdn.simpleicons.org/docker/2496ED'},
  {n:'Linux',      cat:'cloud', i:'https://cdn.simpleicons.org/linux/FCC624'},
  {n:'Python',     cat:'tools', i:'https://cdn.simpleicons.org/python/3776AB'},
  {n:'Bash',       cat:'tools', i:'https://cdn.simpleicons.org/gnubash/4EAA25'},
  {n:'Burp Suite', cat:'tools', i:ICON_B64.burpsuite},
  {n:'OWASP ZAP',  cat:'tools', i:ICON_B64.zap},
  {n:'Trivy',      cat:'tools', i:ICON_B64.trivy},
  {n:'Snyk',       cat:'tools', i:ICON_B64.snyk},
  {n:'SonarQube',  cat:'tools', i:svgBadge('SQ',CAT_COLOR.tools,30)},
  {n:'Checkmarx',  cat:'tools', i:ICON_B64.checkmarx},
  {n:'Jenkins',    cat:'tools', i:ICON_B64.jenkins},
  {n:'Falco',      cat:'tools', i:ICON_B64.falco},
  {n:'Cilium',     cat:'tools', i:ICON_B64.cilium},
  {n:'KubeArmor',  cat:'tools', i:ICON_B64.kubearmor},
  {n:'Calico',     cat:'tools', i:ICON_B64.calico},
  {n:'kube-bench', cat:'tools', i:ICON_B64.kubeBench},
  {n:'Splunk',     cat:'tools', i:'https://cdn.simpleicons.org/splunk/000000'},
  {n:'GH Actions', cat:'tools', i:'https://cdn.simpleicons.org/githubactions/2088FF'},
  {n:'Vuln Mgmt',  cat:'core', i:svgBadge('VM',CAT_COLOR.core,28)},
  {n:'Incident Resp', cat:'core', i:svgBadge('IR',CAT_COLOR.core,28)},
  {n:'Compliance', cat:'core', i:svgBadge('C&amp;A',CAT_COLOR.core,22)},
  {n:'Threat Model', cat:'core', i:svgBadge('TM',CAT_COLOR.core,28)},
  {n:'DevSecOps',  cat:'core', i:svgBadge('DO',CAT_COLOR.core,28)},
  {n:'Pentest',    cat:'core', i:svgBadge('PT',CAT_COLOR.core,28)},
  {n:'Risk Assess', cat:'core', i:svgBadge('RA',CAT_COLOR.core,28)},
  {n:'IAM',        cat:'core', i:svgBadge('IAM',CAT_COLOR.core,22)},
  {n:'Audits',     cat:'core', i:svgBadge('SA',CAT_COLOR.core,28)},
];

(()=>{
  if(typeof THREE==='undefined') return;
  const stage=document.getElementById('arrStage'), canvas=document.getElementById('arrCanvas');
  if(!stage||!canvas) return;

  const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});
  renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.6));
  const scene=new THREE.Scene();
  const camera=new THREE.PerspectiveCamera(50,1,0.1,100);
  let camZ=21; camera.position.z=camZ;
  // Distance is recomputed on every resize so the full sphere (radius R, plus a
  // card's half-diagonal) always sits inside the frustum on both axes — a fixed
  // camZ clipped cards at the poles/edges on narrower or shorter stages, which is
  // what made the cluster read as "not visible".
  function fitCamZ(aspect){
    const fitR=R+0.9;
    const vFov=(camera.fov*Math.PI/180)/2;
    const zV=fitR/Math.tan(vFov);
    const hFov=Math.atan(Math.tan(vFov)*aspect);
    const zH=fitR/Math.tan(hFov);
    return Math.max(zV,zH)*1.08;
  }

  const core=new THREE.Mesh(new THREE.IcosahedronGeometry(1.9,1), new THREE.MeshBasicMaterial({color:threePalette().b,wireframe:true,transparent:true,opacity:0.5}));
  onThemeChange(()=>core.material.color.setHex(threePalette().b));
  scene.add(core);

  const group=new THREE.Group();
  scene.add(group);

  function loadIcon(sk){
    return new Promise(resolve=>{
      const img=new Image();
      if(sk.i.startsWith('http')) img.crossOrigin='anonymous';
      img.onload=()=>resolve(img);
      img.onerror=()=>resolve(null);
      img.src=sk.i;
    });
  }

  function buildSprite(sk,img){
    const cv=document.createElement('canvas'); cv.width=252; cv.height=280;
    const ctx=cv.getContext('2d');
    const ch=CAT_COLOR[sk.cat]||CAT_COLOR.cloud, ar=parseInt(ch.slice(1,3),16), ag=parseInt(ch.slice(3,5),16), ab=parseInt(ch.slice(5,7),16);
    ctx.fillStyle='rgba(9,10,15,0.9)';
    ctx.strokeStyle=`rgba(${ar},${ag},${ab},0.6)`; ctx.lineWidth=2.5;
    ctx.shadowColor=`rgba(${ar},${ag},${ab},0.7)`; ctx.shadowBlur=14;
    roundRect(ctx,6,6,240,268,22); ctx.fill(); ctx.stroke();
    ctx.shadowBlur=0;
    if(img){
      const iw=118, ih=118;
      ctx.drawImage(img,(252-iw)/2,36,iw,ih);
    }
    ctx.fillStyle='#f6f2ff';
    ctx.font='700 25px Inter, sans-serif';
    ctx.textAlign='center';
    ctx.fillText(sk.n, 126, 210, 230);
    ctx.fillStyle=`rgba(${ar},${ag},${ab},0.95)`;
    ctx.font='700 15px JetBrains Mono, monospace';
    ctx.fillText(sk.cat.toUpperCase(), 126, 240);
    const tex=new THREE.CanvasTexture(cv);
    const mat=new THREE.SpriteMaterial({map:tex,transparent:true});
    const spr=new THREE.Sprite(mat);
    spr.scale.set(BASE_SX,BASE_SY,1);
    return spr;
  }
  function roundRect(ctx,x,y,w,h,r){
    ctx.beginPath();
    ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r);
    ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath();
  }

  // Larger sphere + smaller cards + depth-based scale/opacity below keep the
  // cluster readable — the old tight radius with full-opacity cards at every
  // depth made the front and back of the sphere overlap into an unreadable mess.
  const R=9.6, BASE_SX=1.28, BASE_SY=1.42;
  const items=[];
  Promise.all(SKILL_DATA.map(sk=>loadIcon(sk).then(img=>({sk,img})))).then(loaded=>{
    const N=loaded.length;
    loaded.forEach((entry,i)=>{
      const spr=buildSprite(entry.sk,entry.img);
      // Fibonacci sphere distribution
      const off=2/N, y=(i*off)-1+off/2, r=Math.sqrt(Math.max(0,1-y*y));
      const phi=i*Math.PI*(3-Math.sqrt(5));
      spr.userData={
        base:new THREE.Vector3(Math.cos(phi)*r*R, y*R, Math.sin(phi)*r*R),
        cat:entry.sk.cat, visible:true, scaleT:1, depthT:1
      };
      spr.position.copy(spr.userData.base);
      spr.renderOrder=1;
      group.add(spr); items.push(spr);
    });
  });

  // drag to rotate
  let dragging=false, lastX=0, lastY=0, velX=0.002, velY=0.0004;
  const onDown=(x,y)=>{ dragging=true; lastX=x; lastY=y; stage.style.cursor='grabbing'; };
  const onMove=(x,y)=>{
    if(!dragging) return;
    const dx=x-lastX, dy=y-lastY;
    group.rotation.y += dx*0.006;
    group.rotation.x += dy*0.006;
    velX = dx*0.0008; velY = dy*0.0008;
    lastX=x; lastY=y;
  };
  const onUp=()=>{ dragging=false; stage.style.cursor='grab'; };
  stage.style.cursor='grab';
  stage.addEventListener('pointerdown',e=>onDown(e.clientX,e.clientY));
  window.addEventListener('pointermove',e=>onMove(e.clientX,e.clientY));
  window.addEventListener('pointerup',onUp);

  function resize(){
    const r=stage.getBoundingClientRect();
    renderer.setSize(r.width,r.height,false);
    camera.aspect=r.width/r.height; camera.updateProjectionMatrix();
    camZ=fitCamZ(camera.aspect);
  }
  window.addEventListener('resize',resize); resize();
  camera.position.z=camZ;

  // filters
  document.querySelectorAll('.arr-fb').forEach(b=>{
    b.addEventListener('click',()=>{
      document.querySelectorAll('.arr-fb').forEach(x=>x.classList.remove('active'));
      b.classList.add('active');
      const f=b.dataset.f;
      items.forEach(spr=>{ spr.userData.visible = (f==='all'||spr.userData.cat===f); });
    });
  });

  // Gate the loop to when the array section is actually in view — see the
  // same note on the hero-core scene above.
  const wp=new THREE.Vector3();
  let t=0, rafId=null;
  function tick(){
    t+=0.01;
    core.rotation.y+=0.0015; core.rotation.x+=0.0008;
    camera.position.z+=(camZ-camera.position.z)*0.08;
    if(!dragging){
      group.rotation.y+=velX; group.rotation.x+=velY*0;
      velX*=0.96; velY*=0.96;
      group.rotation.y+=0.0012;
    }
    group.updateMatrixWorld(true);
    items.forEach(spr=>{
      const targetScale = spr.userData.visible ? 1 : 0.001;
      spr.userData.scaleT += (targetScale-spr.userData.scaleT)*0.12;
      // depth cue: opacity-only (not size) — shrinking back-of-sphere cards made
      // their baked-in text blur past legibility, which is what made the whole
      // cluster read as "not visible". Keep every card at full, readable size and
      // let fade alone communicate depth, with a high floor so nothing goes ghostly.
      wp.copy(spr.userData.base).applyMatrix4(group.matrixWorld);
      const depthTarget=THREE.MathUtils.clamp((wp.z+R)/(2*R),0,1);
      spr.userData.depthT += (depthTarget-spr.userData.depthT)*0.1;
      spr.scale.set(BASE_SX*spr.userData.scaleT,BASE_SY*spr.userData.scaleT,1);
      spr.material.opacity = spr.userData.scaleT*(0.78+0.22*spr.userData.depthT);
    });
    renderer.render(scene,camera);
    rafId=requestAnimationFrame(tick);
  }
  const arrSection=document.getElementById('array');
  if(arrSection){
    new IntersectionObserver(([e])=>{
      if(e.isIntersecting){ if(!rafId) tick(); }
      else if(rafId){ cancelAnimationFrame(rafId); rafId=null; }
    },{threshold:0.01}).observe(arrSection);
  } else { tick(); }
})();

/* ── BUILD LOG — draggable 3D CSS carousel ── */
(()=>{
  const stage=document.getElementById('carStage'), ring=document.getElementById('carRing');
  if(!stage||!ring) return;
  const panels=Array.from(ring.querySelectorAll('.car-panel'));
  const N=panels.length;
  const halfW=(panels[0]?.offsetWidth || 400)/2;
  const radius=Math.round(halfW/Math.tan(Math.PI/N));
  panels.forEach((p,i)=>{
    const ang=(360/N)*i;
    p.style.transform=`rotateY(${ang}deg) translateZ(${radius}px)`;
    p.dataset.ang=ang;
  });

  // Front-facing panel reads at full size/opacity; anything rotated away
  // from the viewer fades and shrinks instead of sitting there legible-
  // but-skewed — the thing that was making the side cards hard to read.
  function fade(){
    panels.forEach(p=>{
      const ang=parseFloat(p.dataset.ang);
      let eff=(ang+rot)%360; if(eff<0) eff+=360;
      const d=Math.min(eff,360-eff); // angular distance from dead-front (0deg)
      const t=Math.min(1,d/95);
      p.style.opacity=(1-t*0.88).toFixed(3);
      p.style.filter=`brightness(${(1-t*0.5).toFixed(3)}) saturate(${(1-t*0.45).toFixed(3)})`;
      p.style.zIndex=String(Math.round((1-t)*100));
    });
  }

  let rot=0, velocity=0.045, dragging=false, startX=0, startRot=0, moved=0;
  function apply(){ ring.style.transform=`translateZ(-${radius}px) rotateY(${rot}deg)`; fade(); }
  apply();

  function down(x){ dragging=true; startX=x; startRot=rot; moved=0; stage.classList.add('grabbing'); }
  function move(x){ if(!dragging) return; const dx=x-startX; moved=Math.abs(dx); rot=startRot+dx*0.35; apply(); }
  function up(){ dragging=false; stage.classList.remove('grabbing'); }

  stage.addEventListener('pointerdown',e=>down(e.clientX));
  window.addEventListener('pointermove',e=>move(e.clientX));
  window.addEventListener('pointerup',up);
  // prevent link-through only when an actual drag happened
  ring.addEventListener('click',e=>{ if(moved>6){ e.preventDefault(); e.stopPropagation(); } },true);

  document.getElementById('carPrev')?.addEventListener('click',()=>{ rot+=360/N; apply(); });
  document.getElementById('carNext')?.addEventListener('click',()=>{ rot-=360/N; apply(); });

  if(!REDUCE_MOTION){
    function tick(){
      if(!dragging){ rot-=velocity; apply(); }
      requestAnimationFrame(tick);
    }
    tick();
  }
})();

